/// The <t>PurchTable</t> table extension
/// </summary>
[ExtensionOf(tablestr(PurchTable))]
final class METPurchTable_Extension
{
}

Method.Source:
/// <summary>
/// Packs an extension table record to the container field <C>PackedExtensions</C>.
/// </summary>
/// <param name="_METPurchTable">
/// The extension table record.
/// </param>
public void metPackMETPurchTable(METPurchTable _METPurchTable)
{
    _METPurchTable.PurchTable = this.RecId;
    this.SysExtensionSerializerMap::packExtensionTable(_METPurchTable);
}

/// <summary>
/// Get the MET Purch Table
/// </summary>
/// <returns>MET Purch Table</returns>
public METPurchTable metPurchTable()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METPurchTable));
}

    /// <summary>
    /// Inserts a table buffer into the database.
    /// </summary>
    /// <param name = "_interCompanySilent">Inter company silent</param>
    /// <param name = "_accountingDate">Accounting date</param>
    public void insert(boolean _interCompanySilent, AccountingDate _accountingDate)
    {
        METPurchTable metPurchTable;

        next insert(_interCompanySilent, _accountingDate);

        metPurchTable = this.metpurchTable();
        
        if (metPurchTable.RecId == 0)
        {
            this.metPackMETPurchTable(metPurchTable);
            this.SysExtensionSerializerMap::postInsert();
        }

        if (METPurchTable::findByPurchTable(this.RecId) && this.METIntercompanyTransferReplenishment == NoYes::Yes)
        {
            metPurchTable.InternalCustomer = InventLocation::find(this.InventLocationId).metInventLocation().InternalCustomer;
        }

        //CBNF019_Observability_PurchaseOrderProcess
        if (this.RecId != 0)
        {
            METTelemetryPOCreatedInfoEvent::runTelemetryEvent(this);

            //logging Approval status and PO status when puchase order is created
            METTelemetryPOStatusInfoEvent::runTelemetryEvent(this);
            METTelemetryPOApprovalStatusInfoEvent::runTelemetryEvent(this);
        }
        //CBNF019_Observability_PurchaseOrderProcess
    }

    /// <summary>
    /// Create a METPurchTable record
    /// </summary>
    public METPurchTable metCreateMETPurchTable()
    {
        METPurchTable metPurchTable;

        this.metPackMETPurchTable(metPurchTable);
        this.SysExtensionSerializerMap::postInsert();
        
        return this.metPurchTable();
    }

    /// <summary>
    /// Updates a table buffer into the database.
    /// </summary>
    /// <param name = "_updateDistributions">UpdateDistributions</param>
    public void update(boolean _updateDistributions)
    {
        METPurchTable metPurchTable;
        purchTable  purchTableTelOrig = this.orig();

        next update(_updateDistributions);

        metPurchTable = this.metPurchTable();

        if (metPurchTable.InternalCustomer == strMin() && this.METIntercompanyTransferReplenishment == NoYes::Yes)
        {
            metPurchTable.InternalCustomer = InventLocation::find(this.InventLocationId).metInventLocation().InternalCustomer;
        }

        this.SysExtensionSerializerMap::postUpdate();

        //CBNF019_Observability_PurchaseOrderProcess

        if (this.DocumentState != purchTableTelOrig.DocumentState)
        {
            METTelemetryPOApprovalStatusInfoEvent::runTelemetryEvent(this);
        }

        if (this.PurchStatus != purchTableTelOrig.PurchStatus)
        {
            METTelemetryPOStatusInfoEvent::runTelemetryEvent(this);
         
        }
        //CBNF019_Observability_PurchaseOrderProcess
    }

    /// <summary>
    /// To fetch field value of vendor site settup
    /// </summary>
    /// <param name = "_fieldnum"> Field number to ident the field</param>
    /// <returns>anytype value</returns>
    public anytype getVendSiteSettingsSetupFieldValues(FieldId _fieldnum)
    {
        METVendSiteSettingsSetup metVendSiteSettingsSetup;

        select firstonly metVendSiteSettingsSetup 
            Order by Level desc
            where metVendSiteSettingsSetup.AssignedVendorAccount == this.OrderAccount
            &&  ((metVendSiteSettingsSetup.AssignedSite         == this.InventSiteId
            &&  metVendSiteSettingsSetup.AssignedWH             == this.InventLocationId)
            || (metVendSiteSettingsSetup.Level                  == 1
            &&  metVendSiteSettingsSetup.AssignedSite           == this.InventSiteId)
            ||  metVendSiteSettingsSetup.Level                  == 0)
            &&  metVendSiteSettingsSetup.(_fieldnum);

        return metVendSiteSettingsSetup.(_fieldnum);
    }

    /// <summary>
    /// To fetch EDI address or Email value from vendor site setup based on Send method
    /// </summary>
    /// <returns>EDI address or Email value</returns>
    public METEmailAddress getVendSiteSettingsSetupEmailEDI()
    {
        METVendSiteSettingsSetup metVendSiteSettingsSetup;
        METEmailAddress          metEDIEmailAddress;

        select firstonly POSubMode, POEmailAddresses 
            from metVendSiteSettingsSetup 
            Order by Level desc
            where metVendSiteSettingsSetup.AssignedVendorAccount == this.OrderAccount
            &&  ((metVendSiteSettingsSetup.AssignedSite         == this.InventSiteId
            &&  metVendSiteSettingsSetup.AssignedWH             == this.InventLocationId)
            || (metVendSiteSettingsSetup.Level                  == 1
            &&  metVendSiteSettingsSetup.AssignedSite           == this.InventSiteId)
            ||  metVendSiteSettingsSetup.Level                  == 0)
            &&  metVendSiteSettingsSetup.POSubMode;

        if(metVendSiteSettingsSetup.POSubMode == METConstants::Email)
        {
            metEDIEmailAddress =  metVendSiteSettingsSetup.POEmailAddresses;
        }
        else
        {
            metEDIEmailAddress = METConstants::emptyString;
        }

        return metEDIEmailAddress;
    }

    /// <summary>
    /// MPJ_27166_BuyPOFSDEnhancements
    /// To fetch EDI address or Email value from vendor site setup based on Send method
    /// </summary>
    /// <returns>EDI address or Email value</returns>
    public METEmailAddress getVendSiteSettingsSetupEmailChnge()
    {
        METVendSiteSettingsSetup metVendSiteSettingsSetup;
        METEmailAddress          metEDIEmailAddress;

        select firstonly POChngSubMode, POEmailAddresses 
            from metVendSiteSettingsSetup 
            Order by Level desc
            where metVendSiteSettingsSetup.AssignedVendorAccount == this.OrderAccount
            &&  ((metVendSiteSettingsSetup.AssignedSite         == this.InventSiteId
            &&  metVendSiteSettingsSetup.AssignedWH             == this.InventLocationId)
            || (metVendSiteSettingsSetup.Level                  == 1
            &&  metVendSiteSettingsSetup.AssignedSite           == this.InventSiteId)
            ||  metVendSiteSettingsSetup.Level                  == 0)
            &&  metVendSiteSettingsSetup.POChngSubMode;

        if(metVendSiteSettingsSetup.POChngSubMode == METConstants::Email)
        {
            metEDIEmailAddress =  metVendSiteSettingsSetup.POEmailAddresses;
        }
        else
        {
            metEDIEmailAddress = METConstants::emptyString;
        }

        return metEDIEmailAddress;
    }

    /// <summary>
    ///MPJ-30932 - Missing fields on PO Table and Confirmation data entities only
    /// </summary>
    /// <returns>Email address</returns>
    public METWHEmail getPOWarehouseAddressContactEmail()
    {
        LogisticsEntityPostalAddressView    metPostalAddressViewStd;
        LogisticsElectronicAddress          metElectronicAddressStd;
        LogisticsLocation                   metContactLocationStd;
        PurchTable                          metPurchTableStd;
        InventLocation                      metInventLocationStd;

        select firstonly Locator from metElectronicAddressStd
            exists join metPostalAddressViewStd
                exists join metPurchTableStd
            exists join metInventLocationStd
            where metPurchTableStd.InventLocationId == metInventLocationStd.InventLocationId &&
            metPurchTableStd.PurchId          == this.PurchId &&
             metPostalAddressViewStd.Entity     == metInventLocationStd.RecId     &&      metPostalAddressViewStd.EntityType == LogisticsLocationEntityType::Warehouse &&      metPostalAddressViewStd.isPrimary  == NoYes::Yes &&
             metElectronicAddressStd.Type == LogisticsElectronicAddressMethodType::Email
            exists join metContactLocationStd
            where metContactLocationStd.ParentLocation  == metPostalAddressViewStd.Location &&
                  metContactLocationStd.RecId == metElectronicAddressStd.Location;
        return metElectronicAddressStd.Locator;
    }

    /// <summary>
    ///MPJ-30932 - Missing fields on PO Table and Confirmation data entities only
    /// </summary>
    /// <returns>Phone</returns>
    public METWHPhone getPOWarehouseAddressContactPhone()
    {
        LogisticsEntityPostalAddressView    metPostalAddressViewStd;
        LogisticsElectronicAddress          metElectronicAddressStd;
        LogisticsLocation                   metContactLocationStd;
        PurchTable                          metPurchTableStd;
        InventLocation                      metInventLocationStd;

        select firstonly Locator from metElectronicAddressStd
            exists join metPostalAddressViewStd
                exists join metPurchTableStd
            exists join metInventLocationStd
            where metPurchTableStd.InventLocationId == metInventLocationStd.InventLocationId &&
            metPurchTableStd.PurchId          == this.PurchId &&
             metPostalAddressViewStd.Entity     == metInventLocationStd.RecId     &&      metPostalAddressViewStd.EntityType == LogisticsLocationEntityType::Warehouse &&      metPostalAddressViewStd.isPrimary  == NoYes::Yes &&
             metElectronicAddressStd.Type == LogisticsElectronicAddressMethodType::Phone
            exists join metContactLocationStd
            where metContactLocationStd.ParentLocation  == metPostalAddressViewStd.Location &&
                  metContactLocationStd.RecId == metElectronicAddressStd.Location;
        return metElectronicAddressStd.Locator;

    }

    /// <summary>
    /// get the phone based on role type
    /// </summary>
    /// <param name = "_metLogisticsLocationRole">LogisticsLocationRole</param>
    /// <returns>Phone</returns>
    public METWHPhone getPOWarehouseAddressContactPhoneByRole(LogisticsLocationRole _metLogisticsLocationRole)
    {
        LogisticsEntityPostalAddressView    metPostalAddressViewStd;
        LogisticsElectronicAddress          metElectronicAddressStd;
        LogisticsLocation                   metContactLocationStd;
        PurchTable                          metPurchTableStd;
        InventLocation                      metInventLocationStd;
        LogisticsElectronicAddressRole      metElectronicAddressRole;

        select firstonly Locator from metElectronicAddressStd
            exists join metElectronicAddressRole
                where metElectronicAddressRole.LocationRole == _metLogisticsLocationRole.RecId
                    && metElectronicAddressRole.ElectronicAddress == metElectronicAddressStd.RecId
            exists join metPostalAddressViewStd
                exists join metPurchTableStd
            exists join metInventLocationStd
            where metPurchTableStd.InventLocationId == metInventLocationStd.InventLocationId &&
                metPurchTableStd.PurchId          == this.PurchId &&
                metPurchTableStd.DeliveryPostalAddress == metPostalAddressViewStd.PostalAddress &&
                metPostalAddressViewStd.Entity     == metInventLocationStd.RecId     &&      
                metPostalAddressViewStd.EntityType == LogisticsLocationEntityType::Warehouse && 
                metElectronicAddressStd.Type == LogisticsElectronicAddressMethodType::Phone
            exists join metContactLocationStd
            where metContactLocationStd.ParentLocation  == metPostalAddressViewStd.Location &&
                  metContactLocationStd.RecId == metElectronicAddressStd.Location;
        return metElectronicAddressStd.Locator;

    }

    /// <summary>
    /// CB220_PlannerCodes
    /// Method to set PO header buyer group and orderer from item coverage
    /// </summary>
    /// <param name = "_itemId">Item number from the first PO line</param>
    public void METSetItemBuyerGroupId(ItemIdSmall _itemId)
    {
        const str       blank = '';
        ReqItemTable    reqItemTable;
        METReqItemTable metReqItemTable;
        InventDim       inventDimCov;

        // Find matching Item/Site/Warehouse/Vendor record in the Item coverage form
        select firstonly ItemBuyerGroupId from metReqItemTable
                where metReqItemTable.ItemBuyerGroupId
                exists join reqItemTable
                where reqItemTable.ItemId         == _itemId
                &&  reqItemTable.RecId == metReqItemTable.RefRecId
                &&  (reqItemTable.ItemCovFieldsActive == NoYes::Yes)
                exists join inventDimCov
                where inventDimCov.inventDimId == reqItemTable.CovInventDimId
                &&  (inventDimCov.InventSiteId == this.InventSiteId && inventDimCov.InventLocationId == this.InventLocationId);

        // If there is a match, get Buyer group value from Item coverage record and get ordered from buyer group
        if (metReqItemTable.ItemBuyerGroupId)
        {
            this.ItemBuyerGroupId = metReqItemTable.ItemBuyerGroupId;
            this.WorkerPurchPlacer = InventBuyerGroup::find(metReqItemTable.ItemBuyerGroupId).METOrderer;
        }
        //  Else, populate Buyer group as blank on PO header
        else
        {
            this.ItemBuyerGroupId = blank;
        }
    }

		
    /// <summary>
	/// CB714 - POConfirmationReports
    /// get the phone based on role type
    /// </summary>
    /// <param name = "_metLogisticsLocationRole">LogisticsLocationRole</param>
    /// <returns>Phone</returns>
    public METWHPhone getPurchOrderWarehouseAddressContactPhoneByRole(LogisticsLocationRole _metLogisticsLocationRole)
    {
        LogisticsEntityPostalAddressView    metPostalAddressViewStd;
        LogisticsElectronicAddress          metElectronicAddressStd;
        LogisticsLocation                   metContactLocationStd;
        PurchTable                          metPurchTableStd;
        InventLocation                      metInventLocationStd;
        LogisticsElectronicAddressRole      metElectronicAddressRole;

        select firstonly Locator from metElectronicAddressStd
            exists join metElectronicAddressRole
                where metElectronicAddressRole.LocationRole == _metLogisticsLocationRole.RecId
                    && metElectronicAddressRole.ElectronicAddress == metElectronicAddressStd.RecId
            exists join metPostalAddressViewStd
                exists join metPurchTableStd
            exists join metInventLocationStd
            where metPurchTableStd.InventLocationId == metInventLocationStd.InventLocationId 
                && metPurchTableStd.PurchId          == this.PurchId
                && metPurchTableStd.DeliveryPostalAddress == metPostalAddressViewStd.PostalAddress
                && metPostalAddressViewStd.Entity     == metInventLocationStd.RecId
                && metPostalAddressViewStd.EntityType == LogisticsLocationEntityType::Warehouse
                && metElectronicAddressStd.Type == LogisticsElectronicAddressMethodType::Phone
            exists join metContactLocationStd
            where metContactLocationStd.ParentLocation  == metPostalAddressViewStd.Location
                && metContactLocationStd.RecId == metElectronicAddressStd.Location;

        return metElectronicAddressStd.Locator;

    }

    /// <summary>
    /// Bug186328 -CB524- PO header Dates fields are not calculating properly
    /// Handles the modifiedField event for the specified field.
    /// </summary>
    /// <param name = "_fieldId">PurchTable field ID.</param>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch(_fieldId)
        {
            case fieldNum(PurchTable, OrderAccount):
            case fieldNum(PurchTable, InventSiteId):
            case fieldNum(PurchTable, InventLocationId):
                if (VendTable::find(this.OrderAccount).ITMImportCostingVendor == NoYes::Yes)
                {
                    this.modifyRequestedShipDateByLeadTime();
                }
                break;

            // Copy the ‘Return action’ to customer requisition field on purchase order header
            // Anytime, user removes return action on purchase order header, update the customer requisition number to blank
            case fieldNum(PurchTable, METReturnActionId):
                this.PurchOrderFormNum = this.METReturnActionId?this.METReturnActionId:METConstants::emptyString;
                break;
        }
    }

    /// <summary>
    /// Bug186328 -CB524- PO header Dates fields are not calculating properly
    /// Modify requested shipdate by lead time
    /// </summary>
    public void modifyRequestedShipDateByLeadTime()
    {
        METDefaultItemCovLeadTime defaultItemCovLeadTime = METVendSiteSettingsSetup::findByAccountSiteAndLocationId(this.OrderAccount,
                                                                                                                    this.InventSiteId,
                                                                                                                    this.InventLocationId).DefaultItemCovLeadTime;
        utcdatetime startDate = (this.CreatedDateTime == DateTimeUtil::minValue()) ? DateTimeUtil::utcNow() : this.CreatedDateTime;
        utcdatetime newDateTime = DateTimeUtil::addDays(startDate, defaultItemCovLeadTime);
        this.DeliveryDate = DateTimeUtil::date(newDateTime);

        if (this.RecId != 0)
        {
            METPurchTable metPurchTable = METPurchTable::findByPurchTable(this.RecId, true);

            if (metPurchTable)
            {
                ttsbegin;
                metPurchTable.POIMPGoodsReadyNoLtrThanDate = DateTimeUtil::date(newDateTime);
                metPurchTable.POIMPLastShipDate = DateTimeUtil::date(DateTimeUtil::addDays(newDateTime, 7));
                metPurchTable.update();
                ttscommit;
            }
        }
    }

/// <summary>
/// Get Purchase order lines count
/// </summary>
/// <returns>Count of records</returns>
public RecId getCountOflines()
{
    return (select count(RecId) from purchLine
                where purchLine.PurchId == this.PurchId).RecId != 0;
}

/// <summary>
/// Get PO lines count whose qty are negative
/// </summary>
/// <returns>Count of records</returns>
public RecId getCountOfLinesWithNegativeQty()
{
    return (select count(RecId) from purchLine
                where purchLine.PurchId == this.PurchId
                && purchLine.purchQty < 0).RecId != 0;
}

    /// <summary>
    /// Method to  determine if the Purchase order can be confirmed or not. 
    /// A Purchase order will be confirmed if Barcode and Unit price exist for orderline.
    /// </summary>
    /// <param name = "_purchTable">PurchTable buffer</param>
    public void metCanPOBeConfirmed(PurchTable _purchTable)
    {
        if (_purchTable)
        {
            PurchLine purchLine;
            METPurchLine metPurchLine;
            boolean throwError;

            select firstonly LineNumber, PurchPrice, Barcode from purchLine
                where purchLine.PurchId == _purchTable.PurchId
                && (purchLine.BarCode == '' || !purchLine.PurchPrice)
                && !purchLine.IsDeleted;

            if (purchLine.RecId)
            {
                error(strFmt("@MET:OneOrMoreLinesNotSetWithBarcodeOrUnitpriceError", purchLine.LineNumber, purchLine.BarCode, purchLine.PurchPrice));
                throwError = true;
            }

            if (!_purchTable.ItemBuyerGroupId)
            {
                error(strFmt("@MET:BuyerGrpRequiredError", _purchTable.PurchId));
                throwError = true;
            }

            select firstonly RecId from purchLine
                join RecId from metPurchLine
                where metPurchLine.PurchLine == purchLine.RecId
                && metPurchLine.PurchaseWMSFactor == 0
                && purchLine.PurchId == _purchTable.PurchId;

            if (purchLine.RecId && metPurchLine.RecId)
            {
                error(strFmt("@MET:MissingPurchaseWMSFactorForConfirmation", _purchTable.PurchId));
                throwError = true;
            }

            if (throwError)
            {
                throw error("@MET:POConfirmationFailedError");
            }
       }
    }

    /// <summary>
    ///     This method are testing if the current <c>PurchTable</c> can be submitted to workflow.
    /// </summary>
    /// <param name="workflowType">Workflow type</param>
    /// <returns>
    ///     Returns true if the current record can be submitted to workflow, otherwise false.
    /// </returns>
    public boolean canSubmitToWorkflow(str workflowType)
    {
        this.metCanPOBeConfirmed(this);

        boolean ret = next canSubmitToWorkflow();

        return ret;
    }
